// Retire the service worker generated by the previous Create React App build.
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  const legacyCache =
    'sw-precache-v3-sw-precache-webpack-plugin-' + self.registration.scope;

  event.waitUntil(
    Promise.all([
      self.registration.unregister(),
      caches.delete(legacyCache),
    ]).then(() => self.clients.claim())
  );
});
